from collections import OrderedDict

def cache_trace(capacity, ops):
    store = OrderedDict()
    out = []
    for op in ops:
        kind = op[0]
        if kind == "put":
            k, v = op[1], op[2]
            if capacity <= 0:
                continue
            if k in store:
                store.pop(k)
            store[k] = v
            if len(store) > capacity:
                store.popitem(last=False)
        elif kind == "get":
            k = op[1]
            if k in store:
                v = store.pop(k)
                store[k] = v
                out.append(v)
            else:
                out.append(None)
        else:
            k = op[1]
            out.append(store.get(k, None))
    return out

from fractions import Fraction

def evaluate(expr):
    if not isinstance(expr, str):
        return None
    s = expr
    n = len(s)
    pos = 0

    class Bad(Exception):
        pass

    def skip():
        nonlocal pos
        while pos < n and s[pos] == " ":
            pos += 1

    def parse_expr():
        nonlocal pos
        val = parse_term()
        while True:
            skip()
            if pos < n and s[pos] in "+-":
                op = s[pos]
                pos += 1
                rhs = parse_term()
                val = val + rhs if op == "+" else val - rhs
            else:
                return val

    def parse_term():
        nonlocal pos
        val = parse_factor()
        while True:
            skip()
            if pos < n and s[pos] in "*/":
                op = s[pos]
                pos += 1
                rhs = parse_factor()
                if op == "*":
                    val = val * rhs
                else:
                    if rhs == 0:
                        raise Bad()
                    val = val / rhs
            else:
                return val

    def parse_factor():
        nonlocal pos
        skip()
        if pos < n and s[pos] in "+-":
            op = s[pos]
            pos += 1
            v = parse_factor()
            return v if op == "+" else -v
        return parse_power()

    def parse_power():
        nonlocal pos
        base = parse_atom()
        skip()
        if pos < n and s[pos] == "^":
            pos += 1
            e = parse_factor()
            if e.denominator != 1:
                raise Bad()
            e = int(e)
            if base == 0 and e < 0:
                raise Bad()
            return base ** e
        return base

    def parse_atom():
        nonlocal pos
        skip()
        if pos >= n:
            raise Bad()
        if s[pos] == "(":
            pos += 1
            v = parse_expr()
            skip()
            if pos >= n or s[pos] != ")":
                raise Bad()
            pos += 1
            return v
        start = pos
        seen_dot = False
        while pos < n and (s[pos].isdigit() or (s[pos] == "." and not seen_dot)):
            if s[pos] == ".":
                seen_dot = True
            pos += 1
        tok = s[start:pos]
        if tok in ("", "."):
            raise Bad()
        return Fraction(tok)

    try:
        v = parse_expr()
        skip()
        if pos != n:
            return None
        return float(v)
    except Bad:
        return None
    except Exception:
        return None

