def recurrence_term(coeffs, init, n):
    MOD = 1000000007
    k = len(coeffs)
    if n < k:
        return init[n] % MOD
    def mul(A, B):
        size = k
        C = [[0] * size for _ in range(size)]
        for i in range(size):
            Ai = A[i]
            Ci = C[i]
            for x in range(size):
                a = Ai[x]
                if a:
                    Bx = B[x]
                    for j in range(size):
                        Ci[j] = (Ci[j] + a * Bx[j]) % MOD
        return C
    M = [[0] * k for _ in range(k)]
    for j in range(k):
        M[0][j] = coeffs[j] % MOD
    for i in range(1, k):
        M[i][i - 1] = 1
    R = [[1 if i == j else 0 for j in range(k)] for i in range(k)]
    e = n - (k - 1)
    base = M
    while e:
        if e & 1:
            R = mul(R, base)
        base = mul(base, base)
        e >>= 1
    vec = [init[k - 1 - i] % MOD for i in range(k)]
    return sum(R[0][i] * vec[i] for i in range(k)) % MOD

