def hull_double_area(points):
    pts = sorted(set(points))
    if len(pts) < 3:
        return 0

    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    lower = []
    for p in pts:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)
    upper = []
    for p in reversed(pts):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)
    hull = lower[:-1] + upper[:-1]
    if len(hull) < 3:
        return 0
    area2 = 0
    for i in range(len(hull)):
        x1, y1 = hull[i]
        x2, y2 = hull[(i + 1) % len(hull)]
        area2 += x1 * y2 - x2 * y1
    return abs(area2)

from collections import deque

def ladder_length(start, goal, words):
    wordset = set(words)
    if goal not in wordset:
        return 0
    if start == goal:
        return 1
    L = len(start)
    buckets = {}
    for w in wordset:
        if len(w) != L:
            continue
        for i in range(L):
            buckets.setdefault(w[:i] + "*" + w[i + 1:], []).append(w)
    seen = {start}
    q = deque([(start, 1)])
    while q:
        w, d = q.popleft()
        for i in range(L):
            key = w[:i] + "*" + w[i + 1:]
            for nxt in buckets.get(key, ()):
                if nxt in seen:
                    continue
                if nxt == goal:
                    return d + 1
                seen.add(nxt)
                q.append((nxt, d + 1))
            buckets[key] = []
    return 0

def peak_overlap(intervals):
    if not intervals:
        return (0, None)
    events = []
    for s, e in intervals:
        if e <= s:
            continue
        events.append((s, 1))
        events.append((e, -1))
    if not events:
        return (0, None)
    events.sort(key=lambda x: (x[0], x[1]))
    best = 0
    best_t = None
    cur = 0
    for t, d in events:
        cur += d
        if d == 1 and cur > best:
            best = cur
            best_t = t
    if best == 0:
        return (0, None)
    return (best, best_t)

def run_program(program):
    stack = []
    mem = [0] * 16
    out = []
    pc = 0
    steps = 0
    n = len(program)
    LIMIT = 2000000
    while pc < n:
        steps += 1
        if steps > LIMIT:
            return None
        ins = program[pc]
        op = ins[0]
        if op == "PUSH":
            stack.append(ins[1])
            pc += 1
        elif op == "POP":
            if not stack:
                return None
            stack.pop()
            pc += 1
        elif op in ("ADD", "SUB", "MUL"):
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            if op == "ADD":
                stack.append(a + b)
            elif op == "SUB":
                stack.append(a - b)
            else:
                stack.append(a * b)
            pc += 1
        elif op == "DUP":
            if not stack:
                return None
            stack.append(stack[-1])
            pc += 1
        elif op == "SWAP":
            if len(stack) < 2:
                return None
            stack[-1], stack[-2] = stack[-2], stack[-1]
            pc += 1
        elif op == "LOAD":
            i = ins[1]
            if not (0 <= i < 16):
                return None
            stack.append(mem[i])
            pc += 1
        elif op == "STORE":
            i = ins[1]
            if not (0 <= i < 16) or not stack:
                return None
            mem[i] = stack.pop()
            pc += 1
        elif op == "PRINT":
            if not stack:
                return None
            out.append(stack.pop())
            pc += 1
        elif op == "JMP":
            t = ins[1]
            if not (0 <= t <= n):
                return None
            pc = t
        elif op == "JZ":
            if not stack:
                return None
            t = ins[1]
            if not (0 <= t <= n):
                return None
            v = stack.pop()
            pc = t if v == 0 else pc + 1
        elif op == "HALT":
            return out
        else:
            return None
    return out

def roman_value(s):
    if not isinstance(s, str) or not s:
        return None
    vals = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}
    for ch in s:
        if ch not in vals:
            return None
    total = 0
    i = 0
    while i < len(s):
        v = vals[s[i]]
        if i + 1 < len(s) and vals[s[i + 1]] > v:
            total += vals[s[i + 1]] - v
            i += 2
        else:
            total += v
            i += 1
    if total < 1 or total > 3999:
        return None
    table = [(1000, "M"), (900, "CM"), (500, "D"), (400, "CD"), (100, "C"),
             (90, "XC"), (50, "L"), (40, "XL"), (10, "X"), (9, "IX"),
             (5, "V"), (4, "IV"), (1, "I")]
    out = []
    rest = total
    for value, sym in table:
        while rest >= value:
            out.append(sym)
            rest -= value
    if "".join(out) != s:
        return None
    return total

def parse_duration(s):
    if not isinstance(s, str) or not s:
        return None
    neg = False
    body = s
    if body[0] == "-":
        neg = True
        body = body[1:]
    if not body:
        return None
    units = {"d": 86400, "h": 3600, "m": 60, "s": 1}
    order = ["d", "h", "m", "s"]
    last_rank = -1
    total = 0
    i = 0
    n = len(body)
    while i < n:
        start = i
        while i < n and body[i].isdigit():
            i += 1
        if i == start:
            return None
        num = int(body[start:i])
        if i >= n:
            return None
        u = body[i]
        if u not in units:
            return None
        rank = order.index(u)
        if rank <= last_rank:
            return None
        last_rank = rank
        total += num * units[u]
        i += 1
    return -total if neg else total

