def fewest_coins(coins, amount):
    if amount == 0:
        return 0
    INF = float("inf")
    dp = [0] + [INF] * amount
    for c in set(coins):
        if c <= 0 or c > amount:
            continue
        for v in range(c, amount + 1):
            alt = dp[v - c] + 1
            if alt < dp[v]:
                dp[v] = alt
    return -1 if dp[amount] == INF else dp[amount]

def longest_shared(a, b):
    n, m = len(a), len(b)
    if n == 0 or m == 0:
        return ""
    prev = [0] * (m + 1)
    rows = []
    for i in range(n):
        cur = [0] * (m + 1)
        ai = a[i]
        for j in range(m):
            if ai == b[j]:
                cur[j + 1] = prev[j] + 1
            else:
                cur[j + 1] = cur[j] if cur[j] >= prev[j + 1] else prev[j + 1]
        rows.append(cur)
        prev = cur
    out = []
    i, j = n, m
    while i > 0 and j > 0:
        if a[i - 1] == b[j - 1]:
            out.append(a[i - 1])
            i -= 1
            j -= 1
        else:
