def full_match(pattern, text):
    # --- node store: each node is [kind, data, out1, out2]
    # kind 'c' -> data is a predicate over one char, out1 is next
    # kind 's' -> split, out1/out2 are the two branches
    nodes = []

    def new(kind, data):
        nodes.append([kind, data, None, None])
        return len(nodes) - 1

    pos = 0
    n = len(pattern)

    def peek():
        return pattern[pos] if pos < n else None

    def parse_class():
        # pattern[pos] is just past '['
        nonlocal pos
        neg = False
        if peek() == '^':
            neg = True
            pos += 1
        items = []
        while pos < n and pattern[pos] != ']':
            if pattern[pos] == '\\':
                pos += 1
                lo = pattern[pos]
                pos += 1
            else:
                lo = pattern[pos]
                pos += 1
            if pos + 1 < n and pattern[pos] == '-' and pattern[pos + 1] != ']':
                pos += 1
                if pattern[pos] == '\\':
                    pos += 1
                hi = pattern[pos]
                pos += 1
                items.append((lo, hi))
            else:
                items.append((lo, lo))
        pos += 1  # skip ']'

        def pred(ch, items=tuple(items), neg=neg):
            inside = any(a <= ch <= b for a, b in items)
            return (not inside) if neg else inside
        return pred

    def parse_atom():
        nonlocal pos
        ch = pattern[pos]
        if ch == '(':
            pos += 1
            frag = parse_alt()
            pos += 1  # skip ')'
            return frag
        if ch == '[':
            pos += 1
            pred = parse_class()
            i = new('c', pred)
            return (i, [(i, 2)])
        if ch == '.':
            pos += 1
            i = new('c', lambda c: True)
            return (i, [(i, 2)])
        if ch == '\\':
            pos += 1
            lit = pattern[pos]
            pos += 1
            i = new('c', lambda c, lit=lit: c == lit)
            return (i, [(i, 2)])
        pos += 1
        i = new('c', lambda c, lit=ch: c == lit)
        return (i, [(i, 2)])

    def patch(outs, target):
        for idx, slot in outs:
            nodes[idx][slot] = target

    def parse_repeat():
        nonlocal pos
        start, outs = parse_atom()
        while pos < n and pattern[pos] in '*+?':
            op = pattern[pos]
            pos += 1
            if op == '*':
                s = new('s', None)
                nodes[s][2] = start
                patch(outs, s)
                start, outs = s, [(s, 3)]
            elif op == '+':
                s = new('s', None)
                nodes[s][2] = start
                patch(outs, s)
                outs = [(s, 3)]
            else:
                s = new('s', None)
                nodes[s][2] = start
                new_outs = list(outs) + [(s, 3)]
                start, outs = s, new_outs
        return start, outs

    def parse_concat():
        nonlocal pos
        start = None
        outs = []
        while pos < n and pattern[pos] not in '|)':
            s2, o2 = parse_repeat()
            if start is None:
                start, outs = s2, o2
            else:
                patch(outs, s2)
                outs = o2
        if start is None:
            s = new('s', None)          # epsilon fragment
            return s, [(s, 2), (s, 3)]
        return start, outs

    def parse_alt():
        nonlocal pos
        start, outs = parse_concat()
        while pos < n and pattern[pos] == '|':
            pos += 1
            s2, o2 = parse_concat()
            s = new('s', None)
            nodes[s][2] = start
            nodes[s][3] = s2
            start = s
            outs = outs + o2
        return start, outs

    start, outs = parse_alt()
    MATCH = -1
    patch(outs, MATCH)

    # --- Thompson simulation
    def add(state, cur, seen):
        stack = [state]
        while stack:
            st = stack.pop()
            if st is None:
                st = MATCH
            if st in seen:
                continue
            seen.add(st)
            if st == MATCH:
                cur.add(MATCH)
                continue
            if nodes[st][0] == 's':
                stack.append(nodes[st][2])
                stack.append(nodes[st][3])
            else:
                cur.add(st)

    cur = set()
    add(start, cur, set())
    for ch in text:
        nxt = set()
        seen = set()
        for st in cur:
            if st == MATCH:
                continue
            if nodes[st][1](ch):
                add(nodes[st][2], nxt, seen)
        cur = nxt
        if not cur:
            return False
    return MATCH in cur

