def _atom(tok, lo, hi, names):
    t = tok.strip()
    if not t:
        raise ValueError("empty token")
    if names and t.upper() in names:
        return names[t.upper()]
    if not t.isdigit():
        raise ValueError("bad value %r" % tok)
    v = int(t)
    if v < lo or v > hi:
        raise ValueError("value out of range %r" % tok)
    return v


def _parse_field(field, lo, hi, names=None):
    if field == "":
        raise ValueError("empty field")
    out = set()
    for part in field.split(","):
        part = part.strip()
        if part == "":
            raise ValueError("empty list item")
        step = 1
        if "/" in part:
            base, _, sstep = part.partition("/")
            if not sstep.isdigit():
                raise ValueError("bad step %r" % part)
            step = int(sstep)
            if step < 1:
                raise ValueError("step must be >= 1")
            if "/" in sstep:
                raise ValueError("bad step")
        else:
            base = part
        if base == "*":
            a, b = lo, hi
        elif "-" in base[1:] or (base.startswith("-")):
            head, _, tail = base.partition("-")
            a = _atom(head, lo, hi, names)
            b = _atom(tail, lo, hi, names)
            if a > b:
                raise ValueError("reversed range %r" % part)
        else:
            a = _atom(base, lo, hi, names)
            b = hi if "/" in part else a
        for v in range(a, b + 1, step):
            out.add(v)
    if not out:
        raise ValueError("field matched nothing")
    return out


def next_fire(expr, after):
    if not isinstance(expr, str):
        raise ValueError("expression must be a string")
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("expected 5 fields, got %d" % len(fields))
    minutes = _parse_field(fields[0], 0, 59)
    hours = _parse_field(fields[1], 0, 23)
    doms = _parse_field(fields[2], 1, 31)
    months = _parse_field(fields[3], 1, 12, _MONTHS)
    dows_raw = _parse_field(fields[4], 0, 7, _DAYS)
    dows = set(0 if d == 7 else d for d in dows_raw)

    dom_star = fields[2].strip() == "*"
    dow_star = fields[4].strip() == "*"

    start = after.replace(second=0, microsecond=0) + _dt.timedelta(minutes=1)
    limit = after + _dt.timedelta(days=1827)

    smins = sorted(minutes)
    shours = sorted(hours)

    day = start.date()
    end_day = limit.date()
    while day <= end_day:
        if day.month in months:
            dow = (day.weekday() + 1) % 7  # Mon=0 -> cron Sun=0
            if dom_star and dow_star:
                ok = True
            elif dom_star:
                ok = dow in dows
            elif dow_star:
                ok = day.day in doms
            else:
                ok = (day.day in doms) or (dow in dows)
            if ok:
                for h in shours:
                    for m in smins:
                        cand = _dt.datetime(day.year, day.month, day.day, h, m)
                        if cand < start:
                            continue
                        if cand > limit:
                            return None
                        return cand
        day += _dt.timedelta(days=1)
    return None

def min_assignment_cost(cost):
    n = len(cost)
    if n == 0:
        return 0
    INF = float('inf')
    u = [0] * (n + 1)
    v = [0] * (n + 1)
    p = [0] * (n + 1)
    way = [0] * (n + 1)
    for i in range(1, n + 1):
        p[0] = i
        j0 = 0
        minv = [INF] * (n + 1)
        used = [False] * (n + 1)
        row = cost[i - 1]
        while True:
            used[j0] = True
            i0 = p[j0]
            delta = INF
            j1 = -1
            r = cost[i0 - 1]
            ui0 = u[i0]
            for j in range(1, n + 1):
                if not used[j]:
                    cur = r[j - 1] - ui0 - v[j]
                    if cur < minv[j]:
                        minv[j] = cur
                        way[j] = j0
                    if minv[j] < delta:
                        delta = minv[j]
                        j1 = j
            for j in range(n + 1):
                if used[j]:
                    u[p[j]] += delta
                    v[j] -= delta
                else:
                    minv[j] -= delta
            j0 = j1
            if p[j0] == 0:
                break
        while True:
            j1 = way[j0]
            p[j0] = p[j1]
            j0 = j1
            if j0 == 0:
                break
    total = 0
    for j in range(1, n + 1):
        if p[j] != 0:
            total += cost[p[j] - 1][j - 1]
    return total

def solve_2sat(n, clauses):
    if n <= 0:
        return []
    if not clauses:
        return [False] * n
    N = 2 * n + 2

    def idx(l):
        return 2 * l if l > 0 else (-2 * l + 1)

    deg = [0] * N
    for a, b in clauses:
        deg[idx(-a)] += 1
        deg[idx(-b)] += 1
    start = [0] * (N + 1)
    s = 0
    for i in range(N):
        start[i] = s
        s += deg[i]
    start[N] = s
    pos = start[:N]
    adj = [0] * s
    for a, b in clauses:
        u = idx(-a); adj[pos[u]] = idx(b); pos[u] += 1
        u = idx(-b); adj[pos[u]] = idx(a); pos[u] += 1

    index = [0] * N        # 0 = unvisited, else preorder+1
    low = [0] * N
    comp = [-1] * N
    onstk = bytearray(N)
    stk = []
    counter = 1
    ncomp = 0
    work = [0] * N  # edge iterator

    for root in range(2, N):
        if index[root]:
            continue
        call = [root]
        index[root] = low[root] = counter; counter += 1
        stk.append(root); onstk[root] = 1
        work[root] = start[root]
        while call:
            v = call[-1]
            if work[v] < start[v + 1]:
                w = adj[work[v]]
                work[v] += 1
                if not index[w]:
                    index[w] = low[w] = counter; counter += 1
                    stk.append(w); onstk[w] = 1
                    work[w] = start[w]
                    call.append(w)
                elif onstk[w]:
                    if index[w] < low[v]:
                        low[v] = index[w]
            else:
                call.pop()
                if low[v] == index[v]:
                    while True:
                        w = stk.pop()
                        onstk[w] = 0
                        comp[w] = ncomp
                        if w == v:
                            break
                    ncomp += 1
                if call:
                    p = call[-1]
                    if low[v] < low[p]:
                        low[p] = low[v]

    res = [False] * n
    for i in range(1, n + 1):
        ct = comp[2 * i]
        cf = comp[2 * i + 1]
        if ct == cf:
            return None
        # Tarjan emits components in reverse topological order:
        # smaller comp id => later in topological order.
        res[i - 1] = ct < cf
    return res

def best_pack(weights, values, capacity):
    if capacity <= 0 or not weights:
        return 0
    items = [(w, v) for w, v in zip(weights, values) if v > 0 and w <= capacity]
    if not items:
        return 0
    total_v = sum(v for _, v in items)
    INF = float('inf')
    dp = [INF] * (total_v + 1)   # dp[v] = min weight achieving exactly value v
    dp[0] = 0
    reach = 0
    for w, v in items:
        reach += v
        cand = [x + w for x in dp[:reach - v + 1]]
        dp[v:reach + 1] = list(map(min, dp[v:reach + 1], cand))
    for v in range(total_v, -1, -1):
        if dp[v] <= capacity:
            return v
    return 0

import heapq

def window_medians(values, k):
    if not isinstance(k, int) or isinstance(k, bool):
        k = int(k)
    if k <= 0:
        raise ValueError("k must be >= 1")
    n = len(values)
    if k > n:
        return []
    small = []   # max-heap via negation (lower half)
    large = []   # min-heap (upper half)
    delayed = {}
    ssz = lsz = 0

    def prune(heap, is_small):
        while heap:
            num = -heap[0] if is_small else heap[0]
            c = delayed.get(num)
            if c:
                if c == 1:
                    del delayed[num]
                else:
                    delayed[num] = c - 1
                heapq.heappop(heap)
            else:
                break

    def balance():
        nonlocal ssz, lsz
        if ssz > lsz + 1:
            heapq.heappush(large, -heapq.heappop(small))
            ssz -= 1; lsz += 1
            prune(small, True)
        elif ssz < lsz:
            heapq.heappush(small, -heapq.heappop(large))
            lsz -= 1; ssz += 1
            prune(large, False)

    out = []
    odd = k % 2
    for i, v in enumerate(values):
        if not small or v <= -small[0]:
            heapq.heappush(small, -v); ssz += 1
        else:
            heapq.heappush(large, v); lsz += 1
        balance()
        if i >= k:
            old = values[i - k]
            delayed[old] = delayed.get(old, 0) + 1
            if old <= -small[0]:
                ssz -= 1
                if old == -small[0]:
                    prune(small, True)
            else:
                lsz -= 1
                if old == large[0]:
                    prune(large, False)
            balance()
        if i >= k - 1:
            if odd:
                out.append(float(-small[0]))
            else:
                out.append((-small[0] + large[0]) / 2.0)
    return out

def count_primes(n):
    if n < 2:
        return 0
    r = int(n ** 0.5)
    while (r + 1) * (r + 1) <= n:
        r += 1
    while r * r > n:
        r -= 1
    # small[i] = S(n // ?)... use standard Lucy_Hedgehog
    # V = [n//1, n//2, ..., n//r, r-1, r-2, ..., 1]
    small = [i - 1 for i in range(r + 1)]        # small[i] = count for value i
    large = [0] * (r + 1)                        # large[i] = count for value n//i
    for i in range(1, r + 1):
        large[i] = n // i - 1
    for p in range(2, r + 1):
        if small[p] == small[p - 1]:
            continue
        sp = small[p - 1]
        p2 = p * p
        lim = min(r, n // p2)
        for i in range(1, lim + 1):
            d = i * p
            if d <= r:
                large[i] -= large[d] - sp
            else:
                large[i] -= small[n // d] - sp
        for v in range(r, p2 - 1, -1):
            small[v] -= small[v // p] - sp
    return large[1]

def count_crossings(segments):
    n = len(segments)
    if n < 2:
        return 0
    cell = 1
    for x1, y1, x2, y2 in segments:
        a = x1 - x2
        if a < 0:
            a = -a
        b = y1 - y2
        if b < 0:
            b = -b
        if a > cell:
            cell = a
        if b > cell:
            cell = b
    grid = {}
    for i in range(n):
        x1, y1, x2, y2 = segments[i]
        key = ((x1 if x1 < x2 else x2) // cell, (y1 if y1 < y2 else y2) // cell)
        b = grid.get(key)
        if b is None:
            grid[key] = [i]
        else:
            b.append(i)
    total = 0
    segs = segments
    gget = grid.get
    for (cx, cy), bucket in grid.items():
        cand = []
        for dx in (-1, 0, 1):
            for dy in (-1, 0, 1):
                if dx == 0 and dy == 0:
                    continue
                o = gget((cx + dx, cy + dy))
                if o is not None:
                    cand.extend(o)
        m = len(bucket)
        for a in range(m):
            i = bucket[a]
            ax, ay, bx, by = segs[i]
            ux = bx - ax
            uy = by - ay
            others = bucket[a + 1:]
            for j in cand:
                if j > i:
                    others.append(j)
            for j in others:
                px, py, qx, qy = segs[j]
                d1 = ux * (py - ay) - uy * (px - ax)
                d2 = ux * (qy - ay) - uy * (qx - ax)
                if (d1 > 0) == (d2 > 0) or d1 == 0 or d2 == 0:
                    continue
                vx = qx - px
                vy = qy - py
                d3 = vx * (ay - py) - vy * (ax - px)
                d4 = vx * (by - py) - vy * (bx - px)
                if d3 == 0 or d4 == 0 or (d3 > 0) == (d4 > 0):
                    continue
                total += 1
    return total

def connectivity(n, ops):
    m = len(ops)
    # queries positions
    # segment tree over op indices [0, m)
    size = 1
    while size < max(m, 1):
        size *= 2
    tree = [[] for _ in range(2 * size)]

    def add_seg(l, r, e):
        # inclusive l, exclusive r
        l += size
        r += size
        while l < r:
            if l & 1:
                tree[l].append(e)
                l += 1
            if r & 1:
                r -= 1
                tree[r].append(e)
            l >>= 1
            r >>= 1

    active = {}
    for i, op in enumerate(ops):
        t = op[0]
        if t == "add":
            u = op[1]; v = op[2]
            if u > v:
                u, v = v, u
            active[(u, v)] = i
        elif t == "del":
            u = op[1]; v = op[2]
            if u > v:
                u, v = v, u
            st = active.pop((u, v))
            add_seg(st, i, (u, v))
    for (u, v), st in active.items():
        add_seg(st, m, (u, v))

    parent = list(range(n))
    sz = [1] * n
    stack = []

    def find(x):
        while parent[x] != x:
            x = parent[x]
        return x

    res = [None] * m
    # iterative DFS over segment tree
    # node, state
    st = [(1, None)]
    while st:
        node, state = st.pop()
        if state is None:
            cnt = 0
            for (u, v) in tree[node]:
                a = find(u); b = find(v)
                if a == b:
                    continue
                if sz[a] < sz[b]:
                    a, b = b, a
                parent[b] = a
                sz[a] += sz[b]
                stack.append(b)
                cnt += 1
            st.append((node, cnt))
            if node >= size:
                idx = node - size
                if idx < m and ops[idx][0] == "q":
                    u = ops[idx][1]; v = ops[idx][2]
                    res[idx] = find(u) == find(v)
            else:
                st.append((2 * node + 1, None))
                st.append((2 * node, None))
        else:
            for _ in range(state):
                b = stack.pop()
                a = parent[b]
                sz[a] -= sz[b]
                parent[b] = b
    return [r for r in res if r is not None]

def lcs_length(a, b):
    n = len(a)
    m = len(b)
    if n == 0 or m == 0:
        return 0
    if n < m:
        a, b = b, a
        n, m = m, n
    # bitmask over a (length n)
    masks = {}
    for i, ch in enumerate(a):
        masks[ch] = masks.get(ch, 0) | (1 << i)
    full = (1 << n) - 1
    V = full
    for ch in b:
        M = masks.get(ch, 0)
        U = V & M
        V = (V + U) | (V - U)
        V &= full
    return n - bin(V & full).count('1')

def lcs3(a, b, c):
    sa = a.encode() if isinstance(a, str) else bytes(a)
    sb = b.encode() if isinstance(b, str) else bytes(b)
    sc = c.encode() if isinstance(c, str) else bytes(c)
    n = min(len(sa), len(sb), len(sc))
    if n == 0:
        return 0
    if len(sa) > len(sb):
        sa, sb = sb, sa
    if len(sa) > len(sc):
        sa, sc = sc, sa
    # sa is now a shortest string
    M1 = (1 << 61) - 1
    M2 = 2305843009213693669
    import random as _rnd
    _rg = _rnd.Random(0x5DEECE66D)
    B1 = _rg.randrange(256, M1 - 1)
    B2 = _rg.randrange(256, M2 - 1)

    def prefix(s, B, M):
        h = [0] * (len(s) + 1)
        acc = 0
        i = 0
        for ch in s:
            acc = (acc * B + ch + 1) % M
            i += 1
            h[i] = acc
        return h

    cache = {}

    def tables(s):
        key = id(s)
        t = cache.get(key)
        if t is None:
            t = (prefix(s, B1, M1), prefix(s, B2, M2))
            cache[key] = t
        return t

    pw1 = [1]
    pw2 = [1]

    def powers(L):
        while len(pw1) <= L:
            pw1.append(pw1[-1] * B1 % M1)
            pw2.append(pw2[-1] * B2 % M2)

    def hashset(s, L):
        h1, h2 = tables(s)
        powers(L)
        p1 = pw1[L]
        p2 = pw2[L]
        out = {}
        for i in range(len(s) - L + 1):
            k = ((h1[i + L] - h1[i] * p1) % M1) * M2 + ((h2[i + L] - h2[i] * p2) % M2)
            out[k] = i
        return out

    def feasible(L):
        if L == 0:
            return True
        if L > n:
            return False
        if L <= 200:
            # exact: real byte slices, set membership compares contents
            SA = {sa[i:i + L] for i in range(len(sa) - L + 1)}
            SB = {sb[i:i + L] for i in range(len(sb) - L + 1)}
            if not SA:
                return False
            SA &= SB
            if not SA:
                return False
            SC = {sc[i:i + L] for i in range(len(sc) - L + 1)}
            return bool(SA & SC)
        da = hashset(sa, L)
        db = hashset(sb, L)
        common = da.keys() & db.keys()
        if not common:
            return False
        dc = hashset(sc, L)
        common &= dc.keys()
        for k in common:
            cand = sa[da[k]:da[k] + L]
            if sb.find(cand) >= 0 and sc.find(cand) >= 0:
                return True
        return False

    if not feasible(1):
        return 0
    lo = 1
    hi = 2
    while hi <= n and feasible(hi):
        lo = hi
        hi *= 2
    if hi > n:
        hi = n + 1
        if lo < n and feasible(n):
            return n
    # answer in [lo, hi-1]
    while lo < hi - 1:
        mid = (lo + hi) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid
    return lo

def max_k_subarrays(arr, k):
    n = len(arr)
    M = n + 2

    def solve(lam):
        # maximize sum - lam*count ; key = value*M - count (ties -> min count)
        L = lam * M + 1
        cur = None
        best = 0
        for xm in aM:
            if cur is None:
                cur = best - L
            else:
                t = best - L
                if t > cur:
                    cur = t
            cur += xm
            if cur > best:
                best = cur
        # decode
        val = -((-best) // M)
        cnt = val * M - best
        return best, val, cnt

    aM = [x * M for x in arr]
    # bounds
    mx = max(abs(x) for x in arr)
    # kadane max subarray
    cur = 0
    kad = -10**18
    for x in arr:
        cur = x if cur < 0 else cur + x
        if cur > kad:
            kad = cur
    lo = -mx - 1
    hi = max(kad, 0) + 1
    # binary search smallest lam with cntmin(lam) <= k
    while lo < hi:
        mid = (lo + hi) // 2
        if mid < lo:
            mid = lo
        _, _, c = solve(mid)
        if c <= k:
            hi = mid
        else:
            lo = mid + 1
    _, val, _ = solve(lo)
    return int(val + lo * k)
